namespace ghidra.app.plugin.core.datamgr.actions;




using docking;
using docking.action;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.app.plugin.core.datamgr.util;
using ghidra.app.services;
using ghidra.framework.plugintool;
using ghidra.program.model.data;

public class FindBaseDataTypeAction : DockingAction {

	private DataTypeManagerPlugin plugin;

	public FindBaseDataTypeAction(DataTypeManagerPlugin plugin) : base("Show Base Data Type", plugin.getName())
    {
		this.plugin = plugin;

		string menuGroup = "ZVeryLast"; // it's own group; on the bottom
		setPopupMenuData(new MenuData(new string[] { "Show Base Data Type" }, null, menuGroup));

		setEnabled(true);
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return false;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;
		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths.length != 1) {
			return false;
		}

		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();
		if (!(node is DataTypeNode)) {
			return false;
		}

		DataTypeNode dtNode = (DataTypeNode) node;
		DataType dt = dtNode.getDataType();
		return dt is TypeDef || dt is Array || dt is Pointer;
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		GTree gTree = (GTree) context.getContextObject();
		TreePath[] selectionPaths = gTree.getSelectionPaths();
		DataTypeNode dataTypeNode = (DataTypeNode) selectionPaths[0].getLastPathComponent();
		DataType baseDataType = DataTypeUtils.getBaseDataType(dataTypeNode.getDataType());

		PluginTool tool = plugin.getTool();
		DataTypeManagerService service = tool.getService(typeof(DataTypeManagerService));

		SwingUtilities.invokeLater(() => service.setDataTypeSelected(baseDataType));
	}
}
